import {normalizeRoster} from './lineup.js';
import {newId,blankSet} from './repository.js';
import {calculate,teamTotal,calculatedKeys} from './calculations.js';
import {teamName,today,positions,matchFormats,formatFor,courtPositions} from './config.js';
export function makePlayer(values,id=newId('player')){const name=String(values.name||'').trim();if(!name)throw Error('선수 이름을 입력하세요.');if(!positions.includes(values.position))throw Error('포지션을 선택하세요.');const number=String(values.number??'').trim();if(number&&!/^\d{1,3}$/.test(number))throw Error('등번호는 0~999 사이의 숫자로 입력하세요.');return {id,name,number,position:values.position,affiliation:String(values.affiliation||'').trim(),active:values.active!==false,memo:String(values.memo||'').trim()};}
export function makeGame(values,players,ids,placements){if(!/^\d{4}-\d{2}-\d{2}$/.test(values.date)||!Number.isFinite(Date.parse(values.date)))throw Error('경기 날짜를 입력하세요.');if(!values.opponent?.trim()||!values.competition?.trim())throw Error('상대팀과 경기명을 입력하세요.');if(!ids.length)throw Error('출전 선수를 한 명 이상 선택하세요.');if(new Set(ids).size!==ids.length)throw Error('출전 선수가 중복되었습니다.');const format=values.format||Object.keys(matchFormats).find(k=>matchFormats[k].maxSets===Number(values.maxSets));if(!matchFormats[format])throw Error('경기 방식을 선택하세요.');const {maxSets,setsToWin}=matchFormats[format];const layout=placements||ids.map((playerId,i)=>({playerId,role:i<9?'court':'bench',courtPosition:i<9?courtPositions[i]:null}));if(layout.length!==ids.length||new Set(layout.map(p=>p.playerId)).size!==ids.length||layout.some(p=>!ids.includes(p.playerId)))throw Error('참가 선수와 배치가 일치하지 않습니다.');const court=layout.filter(p=>p.role==='court');if(court.length>9||new Set(court.map(p=>p.courtPosition)).size!==court.length||court.some(p=>!courtPositions.includes(p.courtPosition))||layout.some(p=>!['court','bench'].includes(p.role)))throw Error('코트는 서로 다른 9자리까지만 배치할 수 있습니다.');const roster=ids.map((id,order)=>{const p=players.find(p=>p.id===id&&p.active&&!p.deletedAt);if(!p)throw Error('선택한 선수의 활동 상태를 확인하세요.');return {playerId:p.id,name:p.name,position:p.position,number:p.number,...layout.find(x=>x.playerId===id),order}});roster.splice(0,roster.length,...normalizeRoster(roster).map((p,order)=>({...p,order})));return {id:newId('game'),date:values.date,opponent:values.opponent.trim(),competition:values.competition.trim(),team:teamName,location:values.location?.trim()||'',memo:values.memo?.trim()||'',format,maxSets,setsToWin,roster,sets:Array.from({length:maxSets},()=>blankSet(roster)),status:values.date>today()?'scheduled':'in_progress',result:null,createdAt:new Date().toISOString()};}
export function gameResult(game){const target=formatFor(game).setsToWin;let wins=0,losses=0,played=0,empty=false;for(const set of game.sets){const [our,opp]=set.score;if(!Number.isSafeInteger(our)||!Number.isSafeInteger(opp)||our<0||opp<0)throw Error('세트 점수는 0 이상의 정수여야 합니다.');if(our===0&&opp===0){empty=true;continue;}if(empty)throw Error('세트 점수는 1세트부터 순서대로 입력하세요.');if(wins===target||losses===target)throw Error('승패가 결정된 이후 세트 점수가 입력되어 있습니다.');if(our===opp)throw Error('동점인 세트가 있습니다. 최종 점수를 확인하세요.');if(our>opp)wins++;else losses++;played++;}if(wins<target&&losses<target)throw Error(`${target}개 세트를 이긴 팀이 있어야 경기를 종료할 수 있습니다.`);return {wins,losses,played,outcome:wins>losses?'win':'loss'};}
export function completeGame(game){const result=gameResult(game);const unused=game.sets.slice(result.played);if(unused.some(s=>Object.values(s.players).some(raw=>Object.values(raw).some(v=>v>0))||s.opponent.some(v=>v>0)))throw Error('치르지 않은 세트에 기록이 있습니다. 점수와 기록을 확인하세요.');return {...game,status:'completed',result,completedAt:new Date().toISOString()};}
export const rosterFor=(game,i)=>normalizeRoster(game.setRosters?.[i]||game.roster);
export const playedSets=game=>game.sets.map((s,i)=>({s,i})).filter(({s})=>s.score.some(v=>v>0));
export function aggregateRaw(raws){const sum={};for(const raw of raws)for(const[k,v]of Object.entries(raw))if(!calculatedKeys.includes(k))sum[k]=(sum[k]||0)+v;return sum;}
export function gamePlayerTotals(game){return normalizeRoster(game.roster).map(p=>{const sets=game.status==='completed'?playedSets(game):game.sets.map((s,i)=>({s,i}));const entries=sets.filter(({i})=>rosterFor(game,i).some(x=>x.playerId===p.playerId));return {p,raw:aggregateRaw(entries.map(({s})=>s.players[p.playerId]||{})),setCount:entries.length};});}
export function filterGames(games,period='all'){let list=games.filter(g=>g.status==='completed').sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));if(period==='year')list=list.filter(g=>g.date.startsWith(today().slice(0,4)));if(period==='recent')list=list.slice(0,10);return list;}
export function recordSummary(games){const done=games.filter(g=>g.status==='completed'&&g.result);const wins=done.filter(g=>g.result.outcome==='win').length;return {games:done.length,wins,losses:done.length-wins,rate:done.length?wins/done.length*100:null,setWins:done.reduce((n,g)=>n+g.result.wins,0),setLosses:done.reduce((n,g)=>n+g.result.losses,0)};}
export function opponentRecords(games){return [...new Set(games.map(g=>g.opponent))].map(opponent=>({opponent,...recordSummary(games.filter(g=>g.opponent===opponent))}));}
export function cumulativeStats(games,playerId){const done=games.filter(g=>g.status==='completed');const totalRows=done.flatMap(gamePlayerTotals);const playerRows=totalRows.filter(x=>!playerId||x.p.playerId===playerId);const raw=aggregateRaw(playerRows.map(x=>x.raw));const setCount=playerId?playerRows.reduce((n,x)=>n+x.setCount,0):done.reduce((n,g)=>n+playedSets(g).length,0);const team=teamTotal(totalRows.map(x=>x.raw),Math.max(1,done.reduce((n,g)=>n+playedSets(g).length,0)));return {games:playerId?done.filter(g=>g.roster.some(p=>p.playerId===playerId)).length:done.length,setCount,raw,values:calculate(raw,team,Math.max(1,setCount))};}
